-- Email sign-ups use a confirmation link before they can enter the specials list. The opaque token
-- is generated by the server action and only its SHA-256 digest is retained in the database.
alter table public.broadcast_optins
  add column email_confirmation_token_hash text;
alter table public.broadcast_optins
  add constraint broadcast_email_confirmation_hash check (
    email_confirmation_token_hash is null or email_confirmation_token_hash ~ '^[0-9a-f]{64}$'
  );

comment on column public.broadcast_optins.email_confirmation_token_hash is
  'SHA-256 of the one-time email confirmation token. Cleared when the address confirms.';

create or replace function public.request_broadcast_email(
  p_name text, p_email text, p_consent_text text, p_confirmation_token text
) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  max_global_1h constant int := 20;
  max_global_24h constant int := 120;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_email text := lower(trim(coalesce(p_email, '')));
begin
  if char_length(coalesce(p_name, '')) < 2 then
    raise exception 'invalid_name' using errcode = 'P0001';
  end if;
  if char_length(coalesce(p_name, '')) > 100 or char_length(coalesce(p_email, '')) > 254 then
    raise exception 'field_too_long' using errcode = 'P0001';
  end if;
  if v_email is null or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'invalid_contact' using errcode = 'P0001';
  end if;
  if char_length(coalesce(p_consent_text, '')) not between 10 and 500 then
    raise exception 'invalid_consent' using errcode = 'P0001';
  end if;
  if p_confirmation_token is null or p_confirmation_token !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_token' using errcode = 'P0001';
  end if;

  perform pg_advisory_xact_lock(hashtext('broadcast_optin'));
  if (select count(*) from public.broadcast_optins o where o.created_at > now() - interval '1 hour') >= max_global_1h
     or (select count(*) from public.broadcast_optins o where o.created_at > now() - interval '24 hours') >= max_global_24h then
    raise exception 'too_many_requests' using errcode = 'P0001';
  end if;

  -- A repeat request for a confirmed address is deliberately indistinguishable to the guest and
  -- does not disturb existing consent. Pending requests renew the consent and one-time token.
  if exists (
    select 1 from public.broadcast_optins o
    where o.channel = 'email' and o.unsubscribed_at is null and o.confirmed_at is not null
      and lower(o.email) = v_email
  ) then
    return false;
  end if;

  update public.broadcast_optins o
     set consented_at = now(), consent_text = trim(p_consent_text), name = coalesce(v_name, o.name),
         email_confirmation_token_hash = encode(extensions.digest(p_confirmation_token, 'sha256'), 'hex')
   where o.channel = 'email' and o.unsubscribed_at is null and o.confirmed_at is null
     and lower(o.email) = v_email;
  if found then
    return true;
  end if;

  insert into public.broadcast_optins (name, email, channel, consent_text, email_confirmation_token_hash)
  values (v_name, v_email, 'email', trim(p_consent_text), encode(extensions.digest(p_confirmation_token, 'sha256'), 'hex'));
  return true;
end $$;

create or replace function public.confirm_broadcast_email(p_token text)
returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if p_token !~ '^[0-9a-f]{64}$' then return false; end if;
  update public.broadcast_optins
     set confirmed_at = now(), email_confirmation_token_hash = null
   where channel = 'email' and unsubscribed_at is null and confirmed_at is null
     and consented_at >= now() - interval '30 days'
     and email_confirmation_token_hash = encode(extensions.digest(p_token, 'sha256'), 'hex');
  return found;
end $$;

revoke execute on function public.request_broadcast_email(text, text, text, text) from public, anon, authenticated;
grant execute on function public.request_broadcast_email(text, text, text, text) to service_role;
revoke execute on function public.confirm_broadcast_email(text) from public, authenticated;
grant execute on function public.confirm_broadcast_email(text) to anon, service_role;
